import{_ as i,o as a,c as t,ai as n}from"./chunks/framework.BxxKhjs3.js";const c=JSON.parse('{"title":"08-浮点类型（1）","description":"","frontmatter":{},"headers":[],"relativePath":"仓颉入门到实战/08-浮点类型（1）/08-浮点类型（1）.md","filePath":"仓颉入门到实战/08-浮点类型（1）/08-浮点类型（1）.md","lastUpdated":1734480750000,"__rawMarkdown":"# 08-浮点类型（1）\\n\\n浮点类型包括 `Float16`、 `Float32` 和 `Float64`，分别用于表示编码长度为 `16-bit`、 `32-bit` 和 `64-bit` 的浮点数（带小数部分的数\\n\\n字，如 3.14159、8.24 和 0.1 等）的类型。`Float16`、 `Float32` 和 `Float64` 分别对应 IEEE 754 中的半精度格式（即 binary16）、单\\n\\n精度格式（即 binary32）和双精度格式（即 binary64）。\\n\\n`Float64` 的精度约为小数点后 15 位，`Float32` 的精度约为小数点后 6 位，`Float16` 的精度约为小数点后 3 位。使用哪种浮点类\\n\\n型，取决于代码中需要处理的浮点数的性质和范围。**在多种浮点类型都适合的情况下，首选精度高的浮点类型，因为精度低的浮点类型的**\\n\\n**累计计算误差很容易扩散，并且它能精确表示的整数范围也很有限**。\\n\\n## 浮点类型字面量\\n\\n浮点类型字面量有两种进制表示形式：十进制、十六进制。在十进制表示中，一个浮点字面量至少要包含一个整数部分或一个小数部分，\\n\\n没有小数部分时必须包含指数部分（以 `e` 或 `E` 为前缀，底数为 10）。在十六进制表示中，一个浮点字面量除了至少要包含一个整数部\\n\\n分或小数部分（以 `0x` 或 `0X` 为前缀），同时必须包含指数部分（以 `p` 或 `P` 为前缀，底数为 2）。\\n\\n下面的例子展示了浮点字面量的使用：\\n\\n```javascript\\nlet a: Float32 = 3.14\\nlet b: Float32 = 2e3\\nlet c: Float32 = 2.4e-1\\nlet d: Float64 = .123e2\\nlet e: Float64 = 0x1.1p0\\nlet f: Float64 = 0x1p2\\nlet g: Float64 = 0x.2p4\\n```\\n\\n在使用十进制浮点数字面量时，可以通过加入后缀来明确浮点数字面量的类型，后缀与类型的对应为：\\n\\n## 浮点数字面量的后缀表示\\n\\n| 后缀 | 类型    |\\n| :--- | :------ |\\n| f16  | Float16 |\\n| f32  | Float32 |\\n| f64  | Float64 |\\n\\n加入了后缀的浮点数字面量可以像下面的方式来使用：\\n\\n```javascript\\nlet a = 3.14f32   // a is 3.14 with type Float32\\nlet b = 2e3f32    // b is 2e3 with type Float32\\nlet c = 2.4e-1f64 // c is 2.4e-1 with type Float64\\nlet d = .123e2f64 // d is .123e2 with type Float64\\n```\\n"}'),l={name:"仓颉入门到实战/08-浮点类型（1）/08-浮点类型（1）.md"};function e(p,s,h,k,d,r){return a(),t("div",null,[...s[0]||(s[0]=[n("",18)])])}const F=i(l,[["render",e]]);export{c as __pageData,F as default};
